struct TemplateState {
    state: ActorSnapshot,
    pose: TweenPose,
    hibernate: f32,
    update_rate: f32,
    propagate: bool,
    update_error_reported: bool,
    effects: effects::State,
    capture: Option<capture::Capture>,
